<script setup>
import {ref,watch} from 'vue'
import {adminFetch} from './adminApi.js'
import {transferKinds,transferFile} from '../../../shared/dataTransfer.js'
const props=defineProps({apiWrite:Function})
const kind=ref('products'),mode=ref('create'),text=ref(''),format=ref('json'),filename=ref(''),report=ref(null),ack=ref(false),busy=ref(false),error=ref(''),notice=ref(''),offset=ref(0),next=ref(null),applied=ref(false)
const labels={create:'Создать',update:'Обновить',unchanged:'Без изменений',error:'Ошибка'}
function clear(){report.value=null;ack.value=false;applied.value=false;error.value='';notice.value=''}
watch([kind,mode,text],clear);watch(kind,()=>{offset.value=0;next.value=null})
function download(value,name,type='application/json'){const blob=new Blob([value],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function selectFile(e){clear();text.value='';const file=e.target.files?.[0];if(!file)return;if(file.size>4000000){error.value='Файл должен быть не больше 4 МБ';return}filename.value=file.name;format.value=file.name.toLowerCase().endsWith('.csv')?'csv':'json';try{text.value=await file.text()}catch{error.value='Не удалось прочитать файл'}finally{e.target.value=''}}
async function preview(){if(busy.value||!text.value)return;clear();busy.value=true;try{report.value=await props.apiWrite('/api/admin/transfer/preview','POST',{kind:kind.value,mode:mode.value,format:format.value,text:text.value})}catch(e){error.value=e.message}finally{busy.value=false}}
async function apply(){if(busy.value||!report.value?.id||!ack.value||applied.value)return;busy.value=true;error.value='';try{const r=await props.apiWrite('/api/admin/transfer/apply','POST',{id:report.value.id,confirm:true});applied.value=true;notice.value='Импорт завершён: создано '+r.summary.create+', обновлено '+r.summary.update+', без изменений '+r.summary.unchanged}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportPart(part=0){busy.value=true;error.value='';try{const r=await adminFetch('/api/admin/transfer/export?'+new URLSearchParams({kind:kind.value,offset:String(part)}));const data=await r.json();if(!r.ok)throw Error(data.error||'Ошибка экспорта');download(JSON.stringify(data),'nova-'+kind.value+'-'+part+'.json');offset.value=part;next.value=data.next_offset;notice.value='Выгружено записей: '+data.records.length+(next.value!==null?'. Доступна следующая часть.':'. Выгрузка закончена.')}catch(e){error.value=e.message}finally{busy.value=false}}
function sample(csv=false){if(csv){download(kind.value==='products'?'name;category;price;description;sku;stock;published\r\nТестовый товар;Другое;100,50;Описание;IMPORT-001;5;false\r\n':'name;phone;email;note\r\nТестовый покупатель;+79991112233;test@example.ru;Заметка\r\n','nova-'+kind.value+'-example.csv','text/csv;charset=utf-8');return}const examples={products:{name:'Тестовый товар',category:'Другое',price:100.5,description:'Описание',sku:'IMPORT-001',stock:5,published:false},customers:{name:'Тестовый покупатель',phone:'+79991112233',email:'test@example.ru',note:''},pages:{title:'Новая страница',slug:'import-page',content:'Текст',published:false,sections:[]},posts:{title:'Новая статья',slug:'import-post',excerpt:'Краткое описание',content:'Текст',category:'Новости',tags:[],cover_url:'',published:false}};download(JSON.stringify(transferFile(kind.value,[examples[kind.value]]),null,2),'nova-'+kind.value+'-example.json')}
</script>
<template><div class="transfer-workspace"><div class="page-title"><div><span class="eyebrow">ДАННЫЕ САЙТА</span><h1>Импорт и экспорт</h1><p>Проверка файла, просмотр изменений и применение одной операцией.</p></div></div><p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="notice" role="status" class="transfer-notice">{{notice}}</p><section class="panel transfer-panel"><label>Тип данных<select v-model="kind" :disabled="busy"><option v-for="(name,key) in transferKinds" :key="key" :value="key">{{name}}</option></select></label><p>JSON сохраняет все поддерживаемые поля, включая варианты, SEO и секции. CSV доступен для товаров и покупателей. Файлы изображений переносятся отдельно: ссылки проверяются по медиатеке этого сайта. Заказы, пароли и ключи подключений не входят в перенос.</p><div class="transfer-buttons"><button class="row-btn" :disabled="busy" @click="sample()">Пример JSON</button><button v-if="['products','customers'].includes(kind)" class="row-btn" :disabled="busy" @click="sample(true)">Пример CSV</button><button class="row-btn" :disabled="busy" @click="exportPart(0)">Экспорт JSON</button><button v-if="next!==null" class="row-btn" :disabled="busy" @click="exportPart(next)">Скачать следующую часть</button></div><p>Экспорт разбивается на части до 500 записей и 4 МБ. Скачайте все доступные части и импортируйте по очереди. Покупатели выгружаются с контактами и внутренними заметками.</p></section><section class="panel transfer-panel"><h2>Импорт с предварительной проверкой</h2><label>Режим<select v-model="mode" :disabled="busy"><option value="create">Только добавлять новые записи</option><option value="merge">Добавлять и обновлять совпадения</option></select></label><p>Ключ совпадения: артикул товара, нормализованный телефон покупателя, slug страницы или статьи. Отсутствующие поля при обновлении сохраняются. Удалений нет. Пустой артикул означает создание нового товара; дубли артикулов на сайте требуют исправления.</p><label>Файл JSON или CSV<input type="file" accept=".json,.csv,application/json,text/csv" :disabled="busy" @change="selectFile"></label><p v-if="filename">{{filename}} · {{format.toUpperCase()}}</p><button class="primary-btn" :disabled="busy||!text" @click="preview">{{busy?'Обработка…':'Проверить файл'}}</button><template v-if="report"><p role="status">Создать: {{report.summary.create}} · Обновить: {{report.summary.update}} · Без изменений: {{report.summary.unchanged}} · Ошибок: {{report.summary.errors}}</p><p v-if="!report.valid" class="alert">Запись запрещена: исправьте ошибки в файле и проверьте его заново.</p><div class="table-scroll"><table><thead><tr><th>Строка</th><th>Запись</th><th>Действие</th><th>Проверка и изменения</th></tr></thead><tbody><tr v-for="row in report.rows" :key="row.row"><td>{{row.row}}</td><td>{{row.title}}<small>{{row.key}}</small></td><td>{{labels[row.action]}}</td><td><p v-for="e in row.errors" :key="e" class="transfer-error">{{e}}</p><p v-for="w in row.warnings" :key="w">{{w}}</p><details v-if="row.changes?.length"><summary>Изменяемых полей: {{row.changes.length}}</summary><div v-for="c in row.changes" :key="c.field"><strong>{{c.field}}</strong><p>Было: {{c.before}}</p><p>Будет: {{c.after}}</p></div></details></td></tr></tbody></table></div><template v-if="report.valid&&!applied"><p>Проверка действует 30 минут. Перед применением сервер повторно проверит совпадения, изменения записей и ссылки. Импорт обновляемых товаров может заменить остатки и варианты.</p><label class="transfer-confirm"><input v-model="ack" type="checkbox" :disabled="busy"> Проверил изменения и предупреждения, разрешаю применить весь файл</label><button class="primary-btn" :disabled="busy||!ack" @click="apply">Применить проверенный импорт</button></template></template></section></div></template>
<style scoped>.transfer-panel{padding:24px;margin-bottom:20px;display:grid;gap:16px;min-width:0}.transfer-panel h2,.transfer-panel p{margin:0}.transfer-panel p{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.transfer-panel label{display:grid;gap:8px;font-size:13px;font-weight:600}.transfer-panel input:not([type=checkbox]),.transfer-panel select{padding:12px;border:1px solid #ccd9d0;border-radius:8px;max-width:100%;font:inherit}.transfer-buttons{display:flex;flex-wrap:wrap;gap:10px}.transfer-error{color:#a12e2e}.transfer-confirm{display:flex!important;gap:10px;align-items:center}.transfer-panel small{display:block;overflow-wrap:anywhere}.transfer-panel td{vertical-align:top;max-width:350px;overflow-wrap:anywhere}.transfer-notice{padding:16px;background:#e5f4e9}.transfer-panel details div{padding:10px;border-bottom:1px solid #ccd9d0}.transfer-panel button{justify-self:start;white-space:normal}</style>
